import java.util.*;

class Solution {
  public List<Integer> findSubstring(String s, String[] words) {
    List<Integer> ans = new ArrayList<>();
    int k = words[0].length(), count = words.length, n = s.length();
    Map<String, Integer> need = new HashMap<>();
    for (String w : words) need.merge(w, 1, Integer::sum);
    // slide a window over each of the k word alignments
    for (int offset = 0; offset < k; offset++) {
      Map<String, Integer> seen = new HashMap<>();
      int left = offset, used = 0;
      for (int right = offset; right + k <= n; right += k) {
        String w = s.substring(right, right + k);
        if (!need.containsKey(w)) {
          seen.clear();
          used = 0;
          left = right + k;
          continue;
        }
        seen.merge(w, 1, Integer::sum);
        used++;
        while (seen.get(w) > need.get(w)) {
          seen.merge(s.substring(left, left + k), -1, Integer::sum);
          used--;
          left += k;
        }
        if (used == count) ans.add(left);
      }
    }
    return ans;
  }
}
